userscript.function:

const visibleColumn = ['SELECTED', 'SIGNER_COMPANY_NAME', 'SIGNER_NAME', 'SIGNER_EMAIL'];
for(let id of gridObj.columnIds) {
    if(visibleColumn.includes(id) === false) {
        gridObj.setColumnHidden(gridObj.getColIndexById(id), true);
    }
}

gridObj.setColWidth(gridObj.getColIndexById('SIGNER_COMPANY_NAME'), 150);
gridObj.setColWidth(gridObj.getColIndexById('SIGNER_NAME'), 150);
gridObj.setColWidth(gridObj.getColIndexById('SIGNER_EMAIL'), '*');

if(Sepoa.params.DATA) {
    const config = {
        url : window.CONTEXT_NAME + '/SepoaActionController.sux',
        async : false,
    }

    const params = {
        module : 'contract',
        action : 'doDocumentExtra',
        CONT_NO : Sepoa.params.DATA.CONT_NO,
        CONT_GL_SEQ : Sepoa.params.DATA.CONT_GL_SEQ
    };

    const so = sUtils.multipart.send(config, params);
    const extraData = so.result[0];
    const signerList = $share.SIGNER_LIST = so.result[1];
    for(let i in signerList) {
        const signer = signerList[i];
        signer.CONT_SUBJECT = Sepoa.params.DATA.CONT_SUBJECT;

        gridObj.addRow(i, gridObj.getRowsNum());
        for(let entry of Object.entries(signer)) {
            const [key, value] = entry;
            if(gridObj.getColIndexById(key)) {
                gridObj.cells(i, gridObj.getColIndexById(key)).setValue(value);
            }
        }
    }
} else {
    Alert(sUtils.cache.text.get('POA_CONTRACT.STATUS_1'), () => {   // '조회된 데이터가 없습니다.'
        selfObj.close();
    })

}


	var selected = gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).getValue();
    if (selected == 0) {
        gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).setValue(1);
    } else {
        gridObj.cells(rId, gridObj.getColIndexById("SELECTED")).setValue(0);
    }


if(stage == 2) {
    const colId = gridObj.getColumnId(cellInd);
    const target = gridObj.getRowDataObject(rowId)?.SIGNER_ID

    for(let signer of $share.SIGNER_LIST) {
        if(signer.SIGNER_ID == target) {
            signer[colId] = nValue
        }
    }

    return true;
}


const target = gridObj.getAllDataObject().filter(e => e.SELECTED == '1').map(e => e.SIGNER_ID);
const data = $share.SIGNER_LIST.filter(e => target.includes(e.SIGNER_ID));
console.log(data);
if(data.length == 0) {
    Alert(sUtils.cache.text.get('POA_CONTRACT.MESSAGE_0005'));
    return;
}

Confirm(sUtils.cache.text.get('MESSAGE.5013'), function(flag) {     // '메일전송 하시겠습니까?'
    if (flag) {
        const config = {
            url: window.CONTEXT_NAME + '/SepoaActionController.sux',
            on: {
                callback: function(res, config, params) {
                    if (!res.flag) {
                        Alert(res.message);
                    } else {
                        Alert(Sepoa.cache.text.get('MESSAGE.0001'));
                        callback();
                    }
                }
            },
            contentType:'json'
        }

        const params = {
            module : 'sepoa.svc.ct.CT_102_POPUP',
            action : 'doPushResend',
            list : data
        };

        sUtils.multipart.send(config, params);
    }
});
